module.exports = (target, srv, result, keys_as_segments) => {
  if (typeof result !== 'object' || result == null || Array.isArray(result)) return
  const targetName = target.name.replace(`${srv.definition.name}.`, '')
  if (!target.keys) return targetName

  const filteredKeys = [...target.keys].filter(k => !k.isAssociation).map(k => k.name)
  if (!filteredKeys.every(k => k in result)) return

  const keyValuePairs = filteredKeys.reduce((acc, key) => {
    const value = result[key]

    if (Buffer.isBuffer(value)) {
      const base64 = value.toString('base64')
      acc[key] = keys_as_segments ? base64 : `binary'${base64}'`
    } else if (keys_as_segments) {
      acc[key] = value
    } else {
      const el = target.elements[key]
      const needsQuotes = typeof value === 'string' && (el._type !== 'cds.UUID' || el['@odata.Type'] === 'Edm.String')
      acc[key] = needsQuotes ? `'${value}'` : value
    }

    return acc
  }, {})

  if (keys_as_segments) {
    let location = targetName
    for (const k in keyValuePairs) location += `/${keyValuePairs[k]}`
    return encodeURI(location)
  }

  let keys
  const entries = Object.entries(keyValuePairs)
  if (entries.length === 1) {
    keys = entries[0][1]
  } else {
    keys = entries.map(([key, value]) => `${key}=${value}`).join(',')
  }

  return encodeURI(`${targetName}(${keys})`)
}
